let lang;try{lang=localStorage.getItem('orbi-language')||'zh'}catch{lang='zh'}let page=location.pathname.includes('/download')?'download':location.pathname.includes('/about')?'about':'product';
const link=(key,url,t)=>`<a href="${url}" ${page===key?'aria-current="page"':''}>${t[key]}</a>`;
function render(){const t=lang==='zh'?cn:en;document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.title=`Orbi — ${t[page]}`;document.querySelector('#app').innerHTML=`<header><nav class="nav" aria-label="${lang==='zh'?'主导航':'Main navigation'}"><a href="/" class="logo" aria-label="Orbi"><i></i>orbi</a><div class="links">${link('product','/',t)}${link('download','/download/',t)}${link('about','/about/',t)}<button class="lang" id="language" aria-label="${lang==='zh'?'Switch to English':'切换为中文'}">${lang==='zh'?'EN':'中文'}</button></div></nav></header><div class="notice">${t.draft}</div><main class="page-enter">${page==='product'?productPage(t):page==='download'?`<section class="hero"><div class="eyebrow">${t.dtag}</div><h1>${t.dtitle}</h1><p>${t.dintro}</p><div class="download-panel"><div><div class="logo">orbi</div><h3>${t.package}</h3><p>${t.packagep}</p></div><button disabled class="pill disabled">${t.unavailable}</button></div></section><section class="section"><h2 class="reveal">${t.guide}</h2><div class="steps">${[1,2,3].map(i=>`<article class="step reveal"><div class="step-number">0${i}</div><div><h3>${t['s'+i]}</h3><p>${t['s'+i+'p']}</p></div></article>`).join('')}</div></section><section style="background:#f0f0f2"><div class="section"><h2>${t.permissions}</h2><p>${t.permissionIntro}</p>${[1,2,3].map(i=>`<details class="permission"><summary>${t['q'+i]}</summary><p>${t['a'+i]}</p></details>`).join('')}</div></section>`:`<section class="hero about-hero"><div class="eyebrow">${t.atag}</div><h1>${t.atitle}</h1><p>${t.aintro}</p></section><section class="dark"><div class="section reveal"><div class="eyebrow">OUR PHILOSOPHY</div><div class="about-statement">${t.belief}</div><p class="small">${t.beliefnote}</p></div></section><section class="section center reveal"><h2>${t.av}</h2><p>${t.avp}</p><a href="/" class="textlink">${t.explore} ↗</a></section>`}</main><footer class="footer"><div>${t.footer}</div><nav>${link('product','/',t)}${link('download','/download/',t)}${link('about','/about/',t)}<a href="#">${t.top} ↑</a></nav></footer>`;document.querySelector('#language').onclick=()=>{lang=lang==='zh'?'en':'zh';try{localStorage.setItem('orbi-language',lang)}catch{}render()};const obs=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');obs.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(e=>obs.observe(e));setupProduct();updateScroll()}
let scheduled=false;function updateScroll(){scheduled=false;updateProductScroll();const stage=document.querySelector('.stage');if(stage){stage.style.setProperty('--shift',Math.min(scrollY*.12,65)+'px');stage.style.setProperty('--scale',1+Math.min(scrollY/7000,.07))}const story=document.querySelector('.scroll-story');if(story){const r=story.getBoundingClientRect(),p=Math.max(0,Math.min(1,(innerHeight*.4-r.top)/(r.height-innerHeight*.5)));story.style.setProperty('--reveal',.2+p*.8);story.style.setProperty('--progress',p*100+'%')}}addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(updateScroll)}},{passive:true});render();
